/**
 * Original, offline Spanish rehearsal show with three speech feet and WAVs.
 * Synthetic audio comes from buildDemoPackage; none of the cues were inferred
 * by Muse Spark or generated by Modal. No network, keys or live GO.
 */
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildDemoPackage } from '../src/core/demoShow.mjs';
import { importPortableShow, exportPortableShow } from '../src/core/showArchive.mjs';
import {
  createNewShow, addAudioReference, addMockProposal, decideProposal,
} from '../src/core/workspace.mjs';
import { normalizeShowProject } from '../src/core/projectPersistence.mjs';

export const REHEARSAL_DEMO_FILE =
  'demo/RUNQ_ENSAYO_ES.showcompiler.zip';

const TARGETS = Object.freeze([
  {
    name: '01_atmosphere.wav',
    line: 'L4',
    foot: 'Antes de empezar, escucha cómo respira el teatro.',
    label: 'Ambiente tenue del teatro',
  },
  {
    name: '02_clock_bell.wav',
    line: 'L10',
    foot: 'Presta atención: ahora suena una sola campanada.',
    label: 'Campanada del reloj',
  },
  {
    name: '03_finale.wav',
    line: 'L15',
    foot: 'Entonces deja que esta historia se abra por última vez.',
    label: 'Transición luminosa final',
  },
]);

function fileOf(name, bytes) {
  return {
    name,
    size: bytes.byteLength,
    async arrayBuffer() {
      return bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength);
    },
  };
}

export async function buildRehearsalDemoPackage() {
  const scriptUrl = new URL('../fixtures/demo/runq-ensayo-original-es.txt', import.meta.url);
  const scriptText = await readFile(scriptUrl, 'utf8');
  const sourceDemo = await buildDemoPackage();
  const { audioFiles } = await importPortableShow(sourceDemo.archive);
  const byName = new Map(audioFiles.map(file => [file.name, file.bytes]));
  if (byName.size !== TARGETS.length) throw new TypeError('Unexpected source audio count');

  let show = createNewShow({
    id: 'runq-ensayo-es-2026',
    name: 'RUNQ — El último ensayo (prueba original)',
    scriptText,
  });
  const audioMap = new Map();

  for (const target of TARGETS) {
    const bytes = byName.get(target.name);
    if (!bytes) throw new TypeError('Missing original synthetic WAV: ' + target.name);
    show = addAudioReference(show, target.name);
    const assetId = show.assets.at(-1).id;
    audioMap.set(assetId, fileOf(target.name, bytes));
    // Explicitly MANUAL_MOCK: these are authored fixtures, not model responses.
    show = addMockProposal(show, {
      lineId: target.line, assetId, label: target.label,
    });
    show = decideProposal(show, show.proposals.at(-1).id, 'APPROVE');
  }
  show = normalizeShowProject({
    ...show,
    cues: show.cues.map((cue, index) => ({
      ...cue,
      trigger: TARGETS[index].foot,
    })),
  });
  const archive = await exportPortableShow(show, audioMap);
  // Ensure the delivered ZIP can be reopened and carries the real audio.
  const restored = await importPortableShow(archive);
  if (restored.project.cues.length !== 3 || restored.audioFiles.length !== 3 ||
      restored.project.cues.some((cue, i) => cue.trigger !== TARGETS[i].foot)) {
    throw new Error('Rehearsal package integrity check failed');
  }
  return { archive, project: show };
}

if (process.argv[1] &&
    resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const destination = resolve(REHEARSAL_DEMO_FILE);
  const { archive, project } = await buildRehearsalDemoPackage();
  await mkdir(dirname(destination), { recursive: true });
  await writeFile(destination, archive);
  console.log('Saved original Spanish rehearsal ZIP: ' + destination);
  console.log(project.cues.length + ' cues with spoken triggers and ' +
    project.assets.length + ' synthetic WAVs; no AI/provider calls.');
}
